namespace GoEngine.Problems;

/// <summary>Смысл решения задачи: что оно даёт на этом столе и что меняет в дальнейшей партии.</summary>
/// <remarks>
/// <para>
/// Замечание пользователя 2026-10-11: «То, что ты пишешь в разбор, — по сути пустой текст, который
/// и так понятен… Мне надо понять, что мне даёт решение каждой задачи на столе? Какой выигрыш?
/// Какую форму? Какое противодействие противнику будет? И самое главное — как моё решение задачи
/// повлияет на дальнейшую гипотетическую партию на текущем столе?»
/// </para>
/// <para>
/// Поэтому смысл пишется по задаче, а не шаблоном: считанные факты (снятия, дыхания, вердикт
/// перебора) отвечают на «что произошло», а эта строка — на «что это значит». Текст хранится
/// рядом с задачей: у каждой позиции свой вывод, и общей формулировкой его не заменить.
/// </para>
/// <para>
/// Строки сверены с финальными позициями линий (ревизия содержания 2026-10-17): число дыханий,
/// цвет и число снятых камней, глаза и ко названы по позиции, а не по названию задачи. Где линия
/// не доказывает жизнь по глазам, текст говорит об одном глазе, дыханиях и борьбе, а не о жизни.
/// </para>
/// </remarks>
public static class ProblemStrategy
{
    /// <summary>Смысл решения задачи по её идентификатору.</summary>
    /// <param name="problem">Задача.</param>
    /// <returns>Строку о том, что даёт решение; пустая строка — смысл ещё не написан.</returns>
    public static string Of(Problem problem)
    {
        ArgumentNullException.ThrowIfNull(problem);

        return Lines.TryGetValue(problem.Id, out var line) ? line : string.Empty;
    }

